<?php
namespace Tests\Feature\Wallet;
use Tests\TestCase;
use Tests\Support\BlackjackFixture;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\DB;
use App\Models\{CmsUser,CmsUserTransaction,InternalGameRound,WalletLedgerEntry};
use App\Services\InternalGames\{BlackjackService,InternalGameLedgerAuditService};
use App\Services\Wallet\{AssetWalletService,ActiveWalletService};
class BlackjackWalletInvariantTest extends TestCase {
 use DatabaseTransactions,BlackjackFixture;
 protected function setUp():void{parent::setUp();$this->setupBlackjack();}
 public function test_canonical_owner_context_and_double_settlement_transaction_trace():void{
  $child=new CmsUser;$child->forceFill(['username'=>'bj_context','parent_id'=>$this->player->id,'currency'=>'TRY','role'=>'customer','status'=>'normal'])->save();$this->vector(['9H','2S'],['10C','7D'],['10D']);$s=$this->openBlackjack();$this->assertSame($this->player->id,$s->cms_user_id);$this->assertSame($child->id,data_get($s->launch_payload,'wallet_context_user_id'));$svc=app(BlackjackService::class);$r=$svc->startRound($s->session_token,$this->player,10,'wallet-bj-start');$r=$svc->action($s->session_token,$this->player,$r['roundId'],'double','wallet-bj-double',1);$this->assertSame('520.00000000',$this->wallet->fresh()->available_balance);$this->assertSame('520.00000000',(string)$this->player->fresh()->balance);
  $bet=CmsUserTransaction::where('event_type','internal_blackjack_bet')->firstOrFail();foreach(CmsUserTransaction::all()as $tx){$this->assertSame($r['roundId'],$tx->round_id);$this->assertSame($this->player->id,$tx->cms_user_id);$this->assertSame($this->wallet->id,$tx->source_wallet_account_id);if($tx->id!==$bet->id)$this->assertSame($bet->transactionId,$tx->ref_transaction_id);}$this->reconcileBlackjack();
 }
 public function test_open_refund_once_rejects_followup_action_and_keeps_audit():void{
  $this->vector();$s=$this->openBlackjack();$svc=app(BlackjackService::class);$r=$svc->startRound($s->session_token,$this->player,10,'refund-open-start');$x=$svc->refund($r['roundId'],'refund-open',$this->operator);$this->assertSame('refunded',$x['result']);$before=$this->financeHash();$this->assertSame('already_refunded',$svc->refund($r['roundId'],'refund-open-again',$this->operator)['result']);$this->assertSame($before,$this->financeHash());$this->rejectBlackjack(fn()=>$svc->action($s->session_token,$this->player,$r['roundId'],'stand','post-refund-stand',1),'BLACKJACK_ROUND_ALREADY_RESOLVED');$this->assertSame('500.00000000',$this->wallet->fresh()->available_balance);$this->assertSame(1,CmsUserTransaction::where('event_type','internal_blackjack_refund')->count());$this->assertSame(1,DB::table('internal_game_round_events')->where('event_type','internal_game.blackjack.action.rejected')->count());$this->reconcileBlackjack();
 }
 public function test_double_loss_refund_returns_both_funded_debits_once():void{
  $this->vector(['9H','2S'],['10C','9D'],['2D']);$s=$this->openBlackjack();$svc=app(BlackjackService::class);$r=$svc->startRound($s->session_token,$this->player,10,'double-loss-start');$r=$svc->action($s->session_token,$this->player,$r['roundId'],'double','double-loss-action',1);$this->assertSame('loss',$r['outcome']);$this->assertSame('480.00000000',$this->wallet->fresh()->available_balance);$this->assertSame(20.0,$svc->refund($r['roundId'],'double-loss-refund',$this->operator)['refundAmount']);$this->assertSame('500.00000000',$this->wallet->fresh()->available_balance);$this->reconcileBlackjack();
 }
 public function test_natural_win_push_and_unfunded_borrowed_refund_cannot_credit_again():void{
  $this->vector(['AH','KD'],['9C','7S'],['2D']);$s=$this->openBlackjack();$svc=app(BlackjackService::class);$r=$svc->startRound($s->session_token,$this->player,25,'natural-refund-negative');$before=$this->financeHash();$this->rejectBlackjack(fn()=>$svc->refund($r['roundId'],'winning-refund-rejected',$this->operator),'BLACKJACK_REFUND_REJECTED');$this->assertSame($before,$this->financeHash());
  $orig=InternalGameRound::where('round_id',$r['roundId'])->firstOrFail();$forged=$orig->replicate();$forged->fill(['round_id'=>'igr_unfunded_local','request_ref'=>'unfunded-local','status'=>'processing','win_amount'=>0,'win_transaction_id'=>null,'debit_transaction_id'=>null,'raw_result'=>[],'bet_amount'=>10]);$forged->save();$this->rejectBlackjack(fn()=>$svc->refund($forged->round_id,'unfunded-refund',$this->operator),'BLACKJACK_REFUND_REJECTED');$forged->update(['debit_transaction_id'=>$orig->debit_transaction_id]);$this->rejectBlackjack(fn()=>$svc->refund($forged->round_id,'borrowed-refund',$this->operator),'BLACKJACK_REFUND_REJECTED');$this->assertSame($before,$this->financeHash());$this->reconcileBlackjack();
 }
 public function test_failed_ledger_rolls_back_double_transaction_balance_and_round_state():void{
  $this->vector(['9H','2S'],['10C','7D'],['10D']);$s=$this->openBlackjack();$r=app(BlackjackService::class)->startRound($s->session_token,$this->player,10,'rollback-double-start');$before=$this->financeHash();$ledger=\Mockery::mock(InternalGameLedgerAuditService::class);$ledger->shouldReceive('recordDecimal')->once()->andThrow(new \RuntimeException('Injected ledger failure'));$this->app->instance(InternalGameLedgerAuditService::class,$ledger);try{app(BlackjackService::class)->action($s->session_token,$this->player,$r['roundId'],'double','rollback-double',1);$this->fail('Rollback expected');}catch(\RuntimeException $e){$this->assertSame('Injected ledger failure',$e->getMessage());}$this->assertSame($before,$this->financeHash());$round=InternalGameRound::where('round_id',$r['roundId'])->firstOrFail();$this->assertSame(1,data_get($round->raw_result,'version'));$this->assertSame('awaiting_player_action',$round->status);$this->reconcileBlackjack();
 }
 public function test_policy_change_denies_new_double_but_allows_funded_stand_settlement():void{
  $this->vector();$s=$this->openBlackjack();$svc=app(BlackjackService::class);$r=$svc->startRound($s->session_token,$this->player,10,'policy-start');config(['product_wallets.products.internal_games.supported_assets'=>['USD']]);$before=$this->financeHash();try{$svc->action($s->session_token,$this->player,$r['roundId'],'double','policy-double',1);$this->fail('Admission expected');}catch(\App\Services\Wallet\Exceptions\UnsupportedProductWalletException $e){$this->assertSame('unsupported_wallet',$e->details()['reason_code']);}$this->assertSame($before,$this->financeHash());$r=$svc->action($s->session_token,$this->player,$r['roundId'],'stand','policy-stand',1);$this->assertSame('resolved',$r['phase']);$this->reconcileBlackjack();
 }
 public function test_large_balance_payout_and_refund_preserve_cents_and_exact_HUD_value():void{
  $this->credit('90071992546910.29','large-credit');$this->vector(['AH','KD'],['9C','7S'],['2D']);$s=$this->openBlackjack();$r=app(BlackjackService::class)->startRound($s->session_token,$this->player,25,'large-natural');$this->assertSame('90071992547447.79000000',$this->wallet->fresh()->available_balance);$this->assertSame('90071992547447.79',$r['balanceExact']);$html=view('game-provider-front.internal-blackjack',['payload'=>app(BlackjackService::class)->playPayload($s),'session'=>$s])->render();$this->assertStringContainsString('90071992547447.79</strong>',$html);$this->vector(['9H','6S'],['10C','9D'],['2D']);$svc=app(BlackjackService::class);$loss=$svc->startRound($s->session_token,$this->player,10,'large-loss');$svc->action($s->session_token,$this->player,$loss['roundId'],'stand','large-stand',1);$svc->refund($loss['roundId'],'large-refund',$this->operator);$this->assertSame('90071992547447.79000000',$this->wallet->fresh()->available_balance);$this->reconcileBlackjack();
 }
 public function test_wallet_switch_blocked_while_open_then_refund_remains_pinned_to_original_wallet():void{
  $usd=DB::transaction(fn()=>app(AssetWalletService::class)->ensurePrimaryBalanceWallet($this->player,'USD',true));$this->credit('20.00','usd-bj-fund',$usd);$this->vector(['9H','6S'],['10C','9D'],['2D']);$s=$this->openBlackjack();$svc=app(BlackjackService::class);$r=$svc->startRound($s->session_token,$this->player,10,'pinned-start');try{DB::transaction(fn()=>app(ActiveWalletService::class)->switch($this->player,$usd->id));$this->fail('Open hand must block selection');}catch(\App\Services\Wallet\Exceptions\ActiveWalletChangeBlockedException $e){$this->assertContains('open_internal_game_round',array_column($e->reasons(),'code'));}$svc->action($s->session_token,$this->player,$r['roundId'],'stand','pinned-stand',1);$this->assertSame(200,DB::transaction(fn()=>app(ActiveWalletService::class)->switch($this->player,$usd->id))['status']);$svc->refund($r['roundId'],'pinned-try-refund',$this->operator);$this->assertSame('20.00000000',$usd->fresh()->available_balance);$this->assertSame('500.00000000',$this->wallet->fresh()->available_balance);$this->assertSame('500.00000000',(string)$this->player->fresh()->balance);$this->reconcileBlackjack();
 }
 public function test_failed_payout_ledger_rolls_back_entire_natural_round_and_both_transactions():void {
  $this->vector(['AH','KD'],['9C','7S'],['2D']);$s=$this->openBlackjack();$before=$this->financeHash();$ledger=\Mockery::mock(InternalGameLedgerAuditService::class,[app(\App\Services\Wallet\SpendableWalletService::class)])->makePartial();$ledger->shouldReceive('recordDecimal')->withArgs(fn(...$args)=>$args[4]==='internal_game_win_paid')->once()->andThrow(new \RuntimeException('Injected payout ledger failure'));$this->app->instance(InternalGameLedgerAuditService::class,$ledger);
  try{app(BlackjackService::class)->startRound($s->session_token,$this->player,25,'payout-rollback');$this->fail('Rollback expected');}catch(\RuntimeException $e){$this->assertSame('Injected payout ledger failure',$e->getMessage());}$this->assertSame($before,$this->financeHash());$this->assertSame(0,CmsUserTransaction::count());$this->assertSame(0,InternalGameRound::count());$this->reconcileBlackjack();
 }

}
